WITH recent_shipments AS (SELECT *, ROUND(cost, 0) cost_rounded FROM shipments WHERE (order_id IN (28, 39) AND YEAR(delivered_date) >= 2024) OR carrier = 'FedEx'), agg AS (SELECT carrier, CASE WHEN cost >= 102 THEN 'high' WHEN cost >= 21 THEN 'mid' ELSE 'low' END cost_bucket, MIN(cost) min_cost, MIN(cost_rounded) min_cost_rounded FROM recent_shipments GROUP BY carrier, CASE WHEN cost >= 102 THEN 'high' WHEN cost >= 21 THEN 'mid' ELSE 'low' END) SELECT carrier, cost_bucket, min_cost, min_cost_rounded FROM agg WHERE min_cost_rounded >= 75;
